-- =====================================================================
-- Seed de datos - Temporada 2025 (F1, WRC y Turismo Carretera)
-- Motor: PostgreSQL
--
-- Orden de ejecucion: schema.sql -> 001_indices_unicos.sql -> datos_iniciales.sql -> este archivo.
-- Es idempotente: usa ON CONFLICT sobre los indices unicos de la migracion 001 y
-- WHERE NOT EXISTS en las tablas sin indice unico. Las FK se resuelven por id_externo/siglas,
-- nunca por ids fijos, asi que no depende del valor de las secuencias.
--
-- Convenciones:
--   * Todas las fechas TIMESTAMP de evento/sesion/etapa estan en UTC (ver migracion 001).
--   * evento.zona_horaria guarda la zona IANA de la sede.
--   * id_externo de piloto/equipo lleva prefijo de categoria (ej: 'F1:max_verstappen').
--   * id_externo de evento = numero de fecha ('01'..'24'); de sesion = tipo ('Q','R','SQ','S','FINAL');
--     de etapa = 'SS<n>'.
--   * palmares guarda las estadisticas de la TEMPORADA 2025 (no la carrera completa del piloto).
--   * Tiempos/diferencias en segundos; distancias en km.
--
-- Fuentes (consultadas nov-2026): Wikipedia (temporadas 2025 de F1 y WRC y cada rally),
-- lightsoutblog.com (podios F1 2025), juwra.com (tramos Portugal), ACTC (Copa de Oro 2025),
-- La Nacion / genesis24.net / racingcalendar.net (calendario, ganadores y equipos TC 2025).
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- USUARIO (administrador semilla). Password: Admin2025!  -> CAMBIAR en produccion.
-- Hash BCrypt ($2a$, cost 10), compatible con Spring Security BCryptPasswordEncoder.
-- ---------------------------------------------------------------------
VALUES ('Admin', 'Sistema', 'admin@motorsport.local', '$2a$10$ApF3DUwqWLnhTLCNXJuDNuZueObHMF1jpYJfHOrTpPTd97L.kkyjq', 'America/Argentina/Buenos_Aires', '2025-01-01 00:00:00', TRUE)
ON CONFLICT ((lower(email))) DO NOTHING;

-- ---------------------------------------------------------------------
-- CATEGORIA (mismo contenido que datos_iniciales.sql; no duplica)
-- ---------------------------------------------------------------------
SELECT d.nombre, d.siglas, d.descripcion, d.pais_origen, TRUE
FROM (VALUES
    ('Formula 1', 'F1', 'Campeonato internacional de monoplazas.', 'Internacional'),
    ('World Rally Championship', 'WRC', 'Campeonato mundial de rally.', 'Internacional'),
    ('Turismo Carretera', 'TC', 'Categoria de automovilismo de velocidad argentina.', 'Argentina')
) AS d(nombre, siglas, descripcion, pais_origen)
WHERE NOT EXISTS (SELECT 1 FROM categoria c WHERE c.siglas = d.siglas);

-- ---------------------------------------------------------------------
-- TEMPORADA 2025
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- EQUIPO
-- ---------------------------------------------------------------------
ON CONFLICT (id_externo) WHERE id_externo IS NOT NULL DO NOTHING;

-- ---------------------------------------------------------------------
-- PILOTO (en WRC incluye a los copilotos, referenciados por tripulacion.id_copiloto)
-- fecha_nacimiento NULL = dato no relevado.
-- ---------------------------------------------------------------------
ON CONFLICT (id_externo) WHERE id_externo IS NOT NULL DO NOTHING;

-- ---------------------------------------------------------------------
-- EQUIPO_X_PILOTO (F1 y TC). Incluye los cambios de mitad de temporada en F1:
--   Lawson <-> Tsunoda (Red Bull / Racing Bulls) desde la fecha 3, y Colapinto por Doohan (Alpine) desde la fecha 7.
-- rol usa los valores del codigo (Catalogo.ROL_PILOTO / ROL_COPILOTO).
-- La marca del auto en TC queda pendiente para el MVP 6 (la guia la toma de equipo.nombre_corto).
-- ---------------------------------------------------------------------
SELECT (SELECT id_equipo FROM equipo WHERE id_externo = 'F1:mclaren'), (SELECT id_piloto FROM piloto WHERE id_externo = 'F1:lando_norris'), (SELECT id_categoria FROM categoria WHERE siglas = 'F1'), 2025, 4, 1, 'PILOTO', '2025-03-14', '2025-12-07'
WHERE NOT EXISTS (SELECT 1 FROM equipo_x_piloto x WHERE x.id_equipo = (SELECT id_equipo FROM equipo WHERE id_externo = 'F1:mclaren') AND x.id_piloto = (SELECT id_piloto FROM piloto WHERE id_externo = 'F1:lando_norris') AND x.temporada = 2025);
