-- EQUIPO_X_PILOTO de WRC: cada tripulacion aporta su piloto (PILOTO) y su copiloto (COPILOTO).
-- Sin estas filas, el listado de equipos de WRC y la trayectoria de sus pilotos quedan vacios.
-- ---------------------------------------------------------------------
SELECT tr.id_equipo, x.id_piloto, tr.id_categoria, tr.temporada, tr.numero, x.nro, x.rol, t.fecha_inicio, t.fecha_fin
FROM tripulacion tr
JOIN temporada t ON t.id_categoria = tr.id_categoria AND t.anio = tr.temporada
CROSS JOIN LATERAL (VALUES (tr.id_piloto, 1, 'PILOTO'), (tr.id_copiloto, 2, 'COPILOTO')) AS x(id_piloto, nro, rol)
WHERE tr.id_categoria = (SELECT id_categoria FROM categoria WHERE siglas = 'WRC')
  AND tr.temporada = 2025
  AND NOT EXISTS (SELECT 1 FROM equipo_x_piloto ep
                  WHERE ep.id_equipo = tr.id_equipo AND ep.id_piloto = x.id_piloto AND ep.temporada = tr.temporada);

COMMIT;
